const cfg = $('Load Clinic Config').item.json;
const ai = $json.output ?? $json;
if (!cfg.pinecone_namespace || !cfg.sheet_id) { throw new Error('Clinic config incomplete: pinecone_namespace or sheet_id is empty'); }
let isOpen = true;
try {
  const hours = JSON.parse(cfg.hours_json || '{}');
  const now = $now;
  const dayKey = ['sun','mon','tue','wed','thu','fri','sat'][now.weekday % 7];
  const spec = hours[dayKey];
  if (!spec || spec === 'closed') { isOpen = false; }
  else { const [o,c] = spec.split('-').map(Number); const h = now.hour; isOpen = h >= o && h < c; }
} catch (e) { isOpen = true; }
const patient = ai.patient || {};
return { json: {
  clinic: { clinic_id: cfg.clinic_id, clinic_name: cfg.clinic_name, address: cfg.address, staff_email: cfg.staff_email, staff_phone: cfg.staff_phone, twilio_from: cfg.twilio_from, pinecone_index: cfg.pinecone_index, pinecone_namespace: cfg.pinecone_namespace, sheet_id: cfg.sheet_id, drive_folder_id: cfg.drive_folder_id, hours_json: cfg.hours_json, after_hours_message: cfg.after_hours_message, sms_enabled_patient: cfg.sms_enabled_patient, sms_enabled_staff: cfg.sms_enabled_staff, pinecone_min_score: cfg.pinecone_min_score, test_mode: cfg.test_mode, is_open_now: isOpen },
  session_id: cfg.sessionId, timestamp: $now.toISO(), user_message: cfg.chatInput,
  intent: ai.intent || 'unknown', confidence: ai.confidence ?? 0, urgency: ai.urgency || 'normal', summary: ai.summary || '',
  patient: { name: patient.name || '', phone: patient.phone || '', email: patient.email || '', patient_type: patient.patient_type || '', service: patient.service || '', preferred_date: patient.preferred_date || '', preferred_time: patient.preferred_time || '', existing_appt_datetime: patient.existing_appt_datetime || '', new_preferred_datetime: patient.new_preferred_datetime || '', symptoms: patient.symptoms || '', reason: patient.reason || '' },
  bot_response: ''
} };

const ctx = $('Build Context').first().json;
const docs = $input.all();
let maxScore = 0; const chunks = [];
for (const d of docs) { const j = d.json || {}; const s = j.score ?? j.document?.score ?? j.metadata?.score ?? null; if (typeof s === 'number' && s > maxScore) maxScore = s; const t = j.pageContent ?? j.document?.pageContent ?? j.text ?? ''; if (t) chunks.push(t); }
return [{ json: { ...ctx, faq_max_score: maxScore, faq_chunks: chunks.slice(0,5).join('\n---\n') } }];

